		...(completedJourney.zeroServiceWorker === undefined
			? {}
			: {
					zeroServiceWorker: {
						...completedJourney.zeroServiceWorker,
						outputFiles: beforeInventory.serviceWorkers,
						requests: differentialEvents.filter(
							(event) =>
